import csv,sqlite3, collections
conn=sqlite3.connect('db/satscores.db')
cur=conn.cursor()
cur.execute('SELECT cds, sname, dname, AvgScrMath FROM satscores WHERE LOWER(dname) LIKE "%riverside%"')
sats=cur.fetchall()
conn.close()
with open('csv/frpm.csv') as f:
    frpm_map={r['CDSCode']:r['Charter Funding Type'] for r in csv.DictReader(f)}
by_dist=collections.defaultdict(lambda:{'scores':[],'schools':set()})
for cds,sname,dname,math in sats:
    fund=frpm_map.get(cds,'')
    if math is not None:
        by_dist[dname]['scores'].append(math)
    by_dist[dname]['schools'].add((sname,fund if fund else 'Not a Charter School'))
result=[]
for dname,data in by_dist.items():
    avg=sum(data['scores'])/len(data['scores']) if data['scores'] else 0
    if avg > 400:
        for sname,fund in data['schools']:
            if sname: result.append((sname,fund))
for r in result: print(r)
print(f'Total: {len(result)}')

